import{_ as t,c as a,o,a3 as r}from"./chunks/framework.Dokpd4od.js";const m=JSON.parse('{"title":"Quotations and orders","description":"","frontmatter":{},"headers":[],"relativePath":"master/sales/sales/quotations-orders/index.md","filePath":"master/sales/sales/quotations-orders/index.md","lastUpdated":1792041590000}'),s={name:"master/sales/sales/quotations-orders/index.md"};function n(i,e,h,l,d,u){return o(),a("div",null,e[0]||(e[0]=[r('<h1 id="quotations-and-orders" tabindex="-1">Quotations and orders <a class="header-anchor" href="#quotations-and-orders" aria-label="Permalink to &quot;Quotations and orders&quot;">​</a></h1><p>This group covers the first half of the sales story: your customers, the offers you send them, the orders that follow, and how you get paid. You prepare a quotation, send it, and confirm it when the customer agrees. The confirmed quotation becomes a sales order. You then deliver it, invoice it and record the payment.</p><blockquote><p><strong>In simple words:</strong> A quotation is an offer. When the customer says yes, it becomes an order. When they pay the invoice, the sale is done.</p></blockquote><h2 id="the-flow" tabindex="-1">The flow <a class="header-anchor" href="#the-flow" aria-label="Permalink to &quot;The flow&quot;">​</a></h2><p>Here is one sale from start to finish. Azure Interiors wants 5 Camping Hammocks and 10 Smart LED Desk Lamps.</p><ol><li><strong>Customer.</strong> You add Azure Interiors as a customer. See <a href="./manage-customers.html">Manage customers</a>.</li><li><strong>Quotation.</strong> You create a quotation for the hammocks and lamps with prices and a payment term. See <a href="./create-quotation.html">Create a quotation</a>.</li><li><strong>Send.</strong> You email the quotation to Azure Interiors. See <a href="./send-and-confirm-quotation.html">Send and confirm a quotation</a>.</li><li><strong>Confirm.</strong> Azure Interiors agrees, so you confirm the quotation.</li><li><strong>Order.</strong> The quotation is now a sales order. You follow it on <a href="./manage-orders.html">Manage orders</a>.</li><li><strong>Delivery.</strong> The warehouse ships the goods.</li><li><strong>Invoice.</strong> You create the invoice from the order. See <a href="./../invoicing/">Invoicing</a>.</li><li><strong>Payment.</strong> Azure Interiors pays, and you record the payment against the invoice.</li></ol><h2 id="payment" tabindex="-1">Payment <a class="header-anchor" href="#payment" aria-label="Permalink to &quot;Payment&quot;">​</a></h2><p>Payment is the last step of the flow, and it happens in the invoicing part of Aureus, not on the quotation.</p><ul><li><strong>On the quotation.</strong> You choose a <strong>Payment Term</strong>. It says when the customer must pay, for example &quot;30 Days&quot;. The term is copied to the invoice and sets its due date. A customer can carry a default term, see <a href="./manage-customers.html">Manage customers</a>. To set up terms, see <a href="./../../../finance/customer-invoices/payment-terms.html">Payment terms</a>.</li><li><strong>On the invoice.</strong> When the customer pays, you record it on the customer invoice. See <a href="./../../../finance/customer-invoices/create-invoice.html">Create an invoice</a> and <a href="./../../../finance/payments/register-payment.html">Register a payment</a>.</li><li><strong>On the order.</strong> Open the order and click the <strong>Invoices</strong> tab. It lists each invoice with its <strong>Amount Due</strong> and <strong>Payment State</strong>, so you can see at a glance whether the customer has paid.</li></ul><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Aureus records payments after the invoice exists. The quotation itself does not take a payment.</p></div><h2 id="pages-in-this-group" tabindex="-1">Pages in this group <a class="header-anchor" href="#pages-in-this-group" aria-label="Permalink to &quot;Pages in this group&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Page</th><th>What it helps you do</th></tr></thead><tbody><tr><td><a href="./manage-customers.html">Manage customers</a></td><td>Keep the list of people and companies you sell to, with their contacts, addresses and bank accounts.</td></tr><tr><td><a href="./create-quotation.html">Create a quotation</a></td><td>Build an offer with products, prices, taxes and a payment term.</td></tr><tr><td><a href="./optional-products.html">Optional products</a></td><td>Suggest extra items the customer might also like.</td></tr><tr><td><a href="./send-and-confirm-quotation.html">Send and confirm a quotation</a></td><td>Email the offer, preview it, and confirm or cancel it.</td></tr><tr><td><a href="./manage-orders.html">Manage orders</a></td><td>Follow confirmed orders, their invoices, payment status and deliveries.</td></tr></tbody></table><h2 id="before-you-start" tabindex="-1">Before you start <a class="header-anchor" href="#before-you-start" aria-label="Permalink to &quot;Before you start&quot;">​</a></h2><p>Some settings change what the quotation form shows. Check them first in <a href="./../configuration/settings.html">Sales settings</a>. You also need at least one product. See the <a href="./../products-prices/">Products and prices</a> group.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../">Sales overview</a></li><li><a href="./../invoicing/">Invoicing</a></li><li><a href="./../configuration/settings.html">Sales settings</a></li></ul>',16)]))}const p=t(s,[["render",n]]);export{m as __pageData,p as default};
